_SEG = r"(?:[^,()]|\([^()]*\))"; RULES = [("DROP_TABLE", "high", r"\bDROP\s+TABLE\b", "Drops a table and all of its data."), ("DROP_COLUMN", "high", r'\bALTER\s+TABLE\b.*?\bDROP\s+(?:COLUMN\b|(?!CONSTRAINT\b|DEFAULT\b|NOT\b|IDENTITY\b|EXPRESSION\b)[\w"])', "Drops a column; old app versions may break."), ("TRUNCATE", "high", r"^\s*TRUNCATE\b", "Deletes every row in a table."), ("DELETE_NO_WHERE", "high", r"\bDELETE\s+FROM\b(?!.*\bWHERE\b)", "DELETE without WHERE removes all rows."), ("UPDATE_NO_WHERE", "medium", r'(?:^\s*|\bAS\s*\(\s*)UPDATE\s+(?:ONLY\s+)?[\w".]+(?:\s+(?:AS\s+)?\w+)?\s+SET\b(?!.*\bWHERE\b)', "Check this UPDATE has a WHERE clause."), ("SET_NOT_NULL", "medium", r"\bSET\s+NOT\s+NULL\b", "Fails if NULLs exist and scans the whole table."), ("ADD_NOT_NULL_NO_DEFAULT", "medium", r'\bADD\s+(?!CONSTRAINT\b|CHECK\b|PRIMARY\b|UNIQUE\b|FOREIGN\b|EXCLUDE\b)(?:COLUMN\s+)?(?:IF\s+NOT\s+EXISTS\s+)?[\w".]+\s+(?=' + _SEG + r'*?\bNOT\s+NULL\b)(?!' + _SEG + r'*\b(?:DEFAULT|GENERATED)\b)', "NOT NULL column without DEFAULT fails on non-empty tables."), ("ALTER_TYPE", "medium", r'\bALTER\s+(?:COLUMN\s+)?[\w".]+\s+(?:SET\s+DATA\s+)?TYPE\b', "Type change can rewrite the table and lock it."), ("CREATE_INDEX_BLOCKING", "low", r"^\s*CREATE\s+(?:UNIQUE\s+)?INDEX(?!\s+CONCURRENTLY\b)\b", "Use CREATE INDEX CONCURRENTLY to avoid write locks."), ("RENAME", "low", r'^\s*ALTER\s+TABLE\b(?:\s+IF\s+EXISTS)?(?:\s+ONLY)?\s+[\w".]+\s+RENAME\b(?!\s+CONSTRAINT\b)', "Renames break running app code."), ("DROP_SCHEMA", "high", r"\bDROP\s+SCHEMA\b", "Drops a schema and everything in it."), ("DROP_DATABASE", "high", r"\bDROP\s+DATABASE\b", "Drops an entire database."), ("DROP_CONSTRAINT", "medium", r"\bDROP\s+CONSTRAINT\b", "Removing a constraint can allow bad data in."), ("ADD_FK_WITHOUT_NOT_VALID", "medium", r'\bADD\s+(?:CONSTRAINT\s+[\w".]+\s+)?FOREIGN\s+KEY\b(?!.*\bNOT\s+VALID\b)', "Use NOT VALID, then VALIDATE CONSTRAINT, to avoid a long lock."), ("VACUUM_FULL", "medium", r"^\s*VACUUM\s+(?:\([^)]*\bFULL\b[^)]*\)|FULL\b)", "VACUUM FULL rewrites the table under an exclusive lock."), ("LOCK_TABLE", "medium", r"^\s*LOCK\b", "Explicit table locks can block traffic.")]
